calls = {"model": 0}

def fake_encode(texts):                    # stands in for model.encode(batch)
    calls["model"] += 1
    return {t: [round(len(t) / 10, 2), -0.5, 0.25] for t in texts}

cache = {}

def embed(texts):
    missing = [t for t in dict.fromkeys(texts) if t not in cache]
    if missing:
        cache.update(fake_encode(missing))  # one batched call for all new texts
    return [cache[t] for t in texts]

embed(["reset password", "billing help"])
embed(["billing help", "reset password", "billing help"])     # all cache hits

vec = cache["reset password"]
scale = max(abs(x) for x in vec) / 127     # int8: 1 byte per number instead of 4
q = [round(x / scale) for x in vec]
approx = [round(i * scale, 3) for i in q]
print("model calls:", calls["model"], "| cached texts:", len(cache))
print("float:", vec, "-> int8:", q, "-> back:", approx)
